import{_ as n,c as a,b as e,o as p}from"./app-3s85L5-6.js";const t={};function l(i,s){return p(),a("div",null,[...s[0]||(s[0]=[e(`<p>你可以先把这段代码拆成两个问题来看：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它同时做了两件事：</p><ol><li>保证 <code>anatomies</code> 永远是数组。</li><li>尽量让这个数组的引用保持稳定。</li></ol><hr><h2 id="_1-result-data-为什么叫-安全数组" tabindex="-1"><a class="header-anchor" href="#_1-result-data-为什么叫-安全数组"><span>1. <code>result?.data ?? []</code> 为什么叫“安全数组”</span></a></h2><p><code>useList</code> 在请求完成之前，<code>result</code> 可能还不存在：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">result <span class="token operator">===</span> <span class="token keyword">undefined</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这时：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">result<span class="token operator">?.</span>data</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>得到的是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">undefined</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果直接写：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>那么 <code>anatomies</code> 的类型和实际值可能是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">|</span> <span class="token keyword">undefined</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下游使用时就要反复判断：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line">anatomies<span class="token operator">?.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">anatomies<span class="token operator">?.</span>length</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>或者：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>anatomies<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>加上 <code>?? []</code> 后：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>意思是：</p><p>&gt; 有数据就使用数据，没有数据就使用空数组。</p><p>因此 <code>anatomies</code> 始终是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下游可以安全地写：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line">anatomies<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line">anatomies<span class="token punctuation">.</span>length</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是“始终提供安全数组”。</p><hr><h2 id="_2-为什么直接写-可能产生不稳定引用" tabindex="-1"><a class="header-anchor" href="#_2-为什么直接写-可能产生不稳定引用"><span>2. 为什么直接写 <code>?? []</code> 可能产生不稳定引用</span></a></h2><p>这里是理解 <code>useMemo</code> 的关键。</p><p>数组属于引用类型。每次写：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>都会创建一个新的数组。</p><p>例如：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">===</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>结果是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token boolean">false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>虽然两个数组内容都是空的，但它们不是同一个数组对象。</p><p>假设组件重新渲染了很多次，而数据还没有回来：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>每次渲染都会执行一次 <code>[]</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 第一次渲染</span></span>
<span class="line">anatomies <span class="token operator">=</span> 空数组<span class="token constant">A</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第二次渲染</span></span>
<span class="line">anatomies <span class="token operator">=</span> 空数组<span class="token constant">B</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第三次渲染</span></span>
<span class="line">anatomies <span class="token operator">=</span> 空数组<span class="token constant">C</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">空数组<span class="token constant">A</span> <span class="token operator">!==</span> 空数组<span class="token constant">B</span></span>
<span class="line">空数组<span class="token constant">B</span> <span class="token operator">!==</span> 空数组<span class="token constant">C</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这就叫做<strong>引用不稳定</strong>。</p><hr><h2 id="_3-usememo-在这里做了什么" tabindex="-1"><a class="header-anchor" href="#_3-usememo-在这里做了什么"><span>3. <code>useMemo</code> 在这里做了什么</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它的意思是：</p><p>&gt; 只有当 <code>result?.data</code> 发生变化时，才重新计算数组；否则继续返回上一次的数组。</p><p>当 <code>result?.data</code> 一直是 <code>undefined</code> 时：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 第一次渲染</span></span>
<span class="line">useMemo 创建空数组<span class="token constant">A</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第二次渲染，result?.data 没变化</span></span>
<span class="line">继续使用空数组<span class="token constant">A</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第三次渲染，result?.data 没变化</span></span>
<span class="line">继续使用空数组<span class="token constant">A</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此引用保持稳定：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">第一次的 anatomies <span class="token operator">===</span> 第二次的 anatomies</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这不是为了避免什么昂贵计算，因为：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>本身几乎没有计算成本。</p><p>它主要是为了保持数组引用稳定。</p><hr><h2 id="_4-为什么引用稳定有时很重要" tabindex="-1"><a class="header-anchor" href="#_4-为什么引用稳定有时很重要"><span>4. 为什么引用稳定有时很重要</span></a></h2><p>假设把 <code>anatomies</code> 传给一个经过 <code>memo</code> 优化的子组件：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line"><span class="token keyword">const</span> AnatomyList <span class="token operator">=</span> <span class="token function">memo</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token function">AnatomyList</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  anatomies<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">  anatomies<span class="token operator">:</span> AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> anatomies<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">key</span><span class="token script language-javascript"><span class="token script-punctuation punctuation">=</span><span class="token punctuation">{</span>item<span class="token punctuation">.</span>id<span class="token punctuation">}</span></span><span class="token punctuation">&gt;</span></span><span class="token punctuation">{</span>item<span class="token punctuation">.</span>name<span class="token punctuation">}</span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>父组件中：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span><span class="token class-name">AnatomyList</span></span> <span class="token attr-name">anatomies</span><span class="token script language-javascript"><span class="token script-punctuation punctuation">=</span><span class="token punctuation">{</span>anatomies<span class="token punctuation">}</span></span> <span class="token punctuation">/&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果父组件这样写：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>请求还没完成时，每次父组件渲染都会产生新数组：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">旧 anatomies <span class="token operator">!==</span> 新 anatomies</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>React 会认为传给子组件的 props 变了，于是 <code>AnatomyList</code> 也会重新渲染。</p><p>即使两个数组都是空数组，引用不同也会被认为发生了变化。</p><p>使用 <code>useMemo</code> 后：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只要 <code>result?.data</code> 没变，传给子组件的数组引用就不变，<code>memo</code> 才有机会跳过无意义渲染。</p><hr><h2 id="_5-但为什么又说-不需要为了-usememo-而-usememo" tabindex="-1"><a class="header-anchor" href="#_5-但为什么又说-不需要为了-usememo-而-usememo"><span>5. 但为什么又说“不需要为了 useMemo 而 useMemo”</span></a></h2><p>因为不是所有引用变化都会造成实际问题。</p><p>假设你只是在当前组件中直接渲染：</p><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line"><span class="token keyword">return</span> <span class="token punctuation">(</span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span><span class="token plain-text"></span>
<span class="line">    </span><span class="token punctuation">{</span>anatomies<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span></span>
<span class="line">      <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">key</span><span class="token script language-javascript"><span class="token script-punctuation punctuation">=</span><span class="token punctuation">{</span>item<span class="token punctuation">.</span>id<span class="token punctuation">}</span></span><span class="token punctuation">&gt;</span></span><span class="token punctuation">{</span>item<span class="token punctuation">.</span>name<span class="token punctuation">}</span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">}</span><span class="token plain-text"></span>
<span class="line">  </span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里没有：</p><ul><li>把 <code>anatomies</code> 传给 <code>memo</code> 子组件；</li><li>把 <code>anatomies</code> 放进其他 Hook 的依赖数组；</li><li>基于 <code>anatomies</code> 做昂贵计算；</li><li>依赖数组引用判断数据是否变化。</li></ul><p>那么直接写：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>通常就完全足够。</p><p>虽然每次无数据时都会创建新空数组，但创建一个空数组成本非常低，不一定值得增加 <code>useMemo</code> 的复杂度。</p><p>所以评价里的意思是：</p><p>&gt; 不要看到数组就机械地使用 <code>useMemo</code>，先看这个数组的引用稳定性是否真的会影响下游。</p><hr><h2 id="_6-什么叫-下游依赖引用稳定性" tabindex="-1"><a class="header-anchor" href="#_6-什么叫-下游依赖引用稳定性"><span>6. 什么叫“下游依赖引用稳定性”</span></a></h2><p>常见的情况有三种。</p><h3 id="情况一-传给-memo-子组件" tabindex="-1"><a class="header-anchor" href="#情况一-传给-memo-子组件"><span>情况一：传给 <code>memo</code> 子组件</span></a></h3><div class="language-tsx line-numbers-mode" data-highlighter="prismjs" data-ext="tsx"><pre><code class="language-tsx"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span><span class="token class-name">MemoizedList</span></span> <span class="token attr-name">data</span><span class="token script language-javascript"><span class="token script-punctuation punctuation">=</span><span class="token punctuation">{</span>anatomies<span class="token punctuation">}</span></span> <span class="token punctuation">/&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>此时稳定引用可能有价值。</p><h3 id="情况二-放进其他-hook-的依赖数组" tabindex="-1"><a class="header-anchor" href="#情况二-放进其他-hook-的依赖数组"><span>情况二：放进其他 Hook 的依赖数组</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">doSomething</span><span class="token punctuation">(</span>anatomies<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>anatomies<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果无数据时每次都创建新空数组，Effect 可能每次渲染都执行：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因为每次的 <code>anatomies</code> 都是不同引用。</p><p>使用稳定空数组后可以避免这种情况。</p><p>不过很多时候，更合理的是直接依赖原始数据：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">useEffect</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">doSomething</span><span class="token punctuation">(</span>result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="情况三-作为另一个-usememo-的依赖" tabindex="-1"><a class="header-anchor" href="#情况三-作为另一个-usememo-的依赖"><span>情况三：作为另一个 <code>useMemo</code> 的依赖</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> grouped <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">groupAnatomies</span><span class="token punctuation">(</span>anatomies<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>anatomies<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 <code>anatomies</code> 每次都是新空数组，那么 <code>grouped</code> 也会每次重新计算。</p><hr><h2 id="_7-为什么依赖-result-data-比-result-更准确" tabindex="-1"><a class="header-anchor" href="#_7-为什么依赖-result-data-比-result-更准确"><span>7. 为什么依赖 <code>[result?.data]</code> 比 <code>[result]</code> 更准确</span></a></h2><p>原代码是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>标准答案是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原因是你真正关心的是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">result<span class="token punctuation">.</span>data</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>而不是整个：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">result</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>假设 Refine 每次渲染都返回一个新的 <code>result</code> 对象：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">resultA <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  data<span class="token operator">:</span> dataA<span class="token punctuation">,</span></span>
<span class="line">  total<span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">resultB <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  data<span class="token operator">:</span> dataA<span class="token punctuation">,</span></span>
<span class="line">  total<span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>虽然：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">resultA <span class="token operator">!==</span> resultB</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>但它们内部的 <code>data</code> 可能还是同一个引用：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">resultA<span class="token punctuation">.</span>data <span class="token operator">===</span> resultB<span class="token punctuation">.</span>data</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>依赖整个 <code>result</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span>result<span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>会导致 <code>useMemo</code> 重新计算。</p><p>依赖具体使用的值：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>只有数据数组真正变化时才重新计算。</p><p>可以理解为：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 依赖范围太大</span></span>
<span class="line"><span class="token punctuation">[</span>result<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 精确依赖</span></span>
<span class="line"><span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不过，这里的重新计算本身非常简单，所以主要是代码语义更加精确，而不是性能差距很大。</p><hr><h2 id="_8-模块级-empty-array-是什么方案" tabindex="-1"><a class="header-anchor" href="#_8-模块级-empty-array-是什么方案"><span>8. 模块级 <code>EMPTY_ARRAY</code> 是什么方案</span></a></h2><p>还可以在组件外创建一个固定的空数组：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token operator">:</span> AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>组件中：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因为 <code>EMPTY_ANATOMIES</code> 只在模块加载时创建一次，所以每次没有数据时，使用的都是同一个数组引用：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token constant">EMPTY_ANATOMIES</span> <span class="token operator">===</span> <span class="token constant">EMPTY_ANATOMIES</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这样不需要 <code>useMemo</code>，也能保持稳定引用。</p><p>完整写法：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token operator">:</span> AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">AnatomyPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> result <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token generic-function"><span class="token function">useList</span><span class="token generic class-name"><span class="token operator">&lt;</span>AnatomySummary<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    resource<span class="token operator">:</span> ResourceName<span class="token punctuation">.</span>anatomies<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> total <span class="token operator">=</span> result<span class="token operator">?.</span>total <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种写法在“只需要稳定的默认空数组”时很清楚。</p><p>注意，不要修改这个共享空数组：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 不要这样</span></span>
<span class="line">anatomies<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>newItem<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>通常查询数据本身也不应该直接被修改。</p><p>还可以冻结它：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token operator">:</span> <span class="token keyword">readonly</span> AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>但这会让类型变成只读数组，需要看下游是否接受。</p><hr><h2 id="_9-为什么-total-不需要-usememo" tabindex="-1"><a class="header-anchor" href="#_9-为什么-total-不需要-usememo"><span>9. 为什么 <code>total</code> 不需要 <code>useMemo</code></span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> total <span class="token operator">=</span> result<span class="token operator">?.</span>total <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>total</code> 是数字，数字是原始值。</p><p>对于数字：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token number">0</span> <span class="token operator">===</span> <span class="token number">0</span> <span class="token comment">// true</span></span>
<span class="line"><span class="token number">10</span> <span class="token operator">===</span> <span class="token number">10</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>不存在“每次创建一个新的数字对象”这种问题。</p><p>数组不同：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">===</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>数字相同：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token number">0</span> <span class="token operator">===</span> <span class="token number">0</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>所以没必要写：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> total <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>total <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>total<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这不仅没有实际收益，反而增加了代码复杂度。</p><hr><h2 id="_10-这三种写法怎么选" tabindex="-1"><a class="header-anchor" href="#_10-这三种写法怎么选"><span>10. 这三种写法怎么选</span></a></h2><h3 id="普通场景-推荐最简单的" tabindex="-1"><a class="header-anchor" href="#普通场景-推荐最简单的"><span>普通场景，推荐最简单的</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>适合：</p><ul><li>只在当前组件里使用；</li><li>没有放入依赖数组；</li><li>没有传给 <code>memo</code> 子组件；</li><li>不在意空数组引用变化。</li></ul><h3 id="明确需要稳定引用" tabindex="-1"><a class="header-anchor" href="#明确需要稳定引用"><span>明确需要稳定引用</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合：</p><ul><li>传给 <code>memo</code> 子组件；</li><li>作为其他 Hook 的依赖；</li><li>引用变化会触发额外工作。</li></ul><h3 id="只想稳定默认空数组" tabindex="-1"><a class="header-anchor" href="#只想稳定默认空数组"><span>只想稳定默认空数组</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token operator">:</span> AnatomySummary<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token constant">EMPTY_ANATOMIES</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合：</p><ul><li>不想使用 <code>useMemo</code>；</li><li>只是为了避免反复创建默认空数组。</li></ul><hr><h2 id="最核心的理解" tabindex="-1"><a class="header-anchor" href="#最核心的理解"><span>最核心的理解</span></a></h2><p><code>useMemo</code> 不只是“缓存昂贵计算”，它还可以缓存一个数组或对象的<strong>引用</strong>。</p><p>但是否需要缓存，要看这个引用是否会影响下游：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 简单、安全，通常足够</span></span>
<span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 当引用稳定确实有意义时再用</span></span>
<span class="line"><span class="token keyword">const</span> anatomies <span class="token operator">=</span> <span class="token function">useMemo</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> result<span class="token operator">?.</span>data <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>result<span class="token operator">?.</span>data<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>所以这道题标准答案的重点并不是：</p><p>&gt; 数组必须使用 <code>useMemo</code>。</p><p>而是：</p><p>&gt; 对外提供安全数组；需要引用稳定时，再用 <code>useMemo</code> 或模块级空数组。</p>`,186)])])}const o=n(t,[["render",l]]),r=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%9D%A2%E8%AF%95/%E5%85%AB%E8%82%A1/React/Hooks/useMemo%E7%9A%84%E5%AE%89%E5%85%A8%E6%95%B0%E7%BB%84.html","title":"","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/面试/八股/React/Hooks/useMemo的安全数组.md"}');export{o as comp,r as data};
